function drawObstacle(o){if(o.z<0||o.z>145)return;const [x,y,s]=project(o.x,o.z),w=W*.045*s,h=H*.08*s;ctx.fillStyle='#262b25';ctx.fillRect(x-w/2,y-h,w,h);ctx.fillStyle='#ca603f';ctx.fillRect(x-w/2,y-h,w,h*.22);ctx.fillStyle='#d9c79a';ctx.fillRect(x-w*.38,y-h*.62,w*.76,h*.09)}
function drawRace(t){drawSky(true);const horizon=H*.37;ctx.fillStyle='#657253';ctx.fillRect(0,horizon,W,H-horizon);const bend=Math.sin(roadOffset*.22)*W*.09;const topW=W*.115,bottomW=W*.48,cx=W/2+bend;pathPoly([[cx-topW,horizon],[cx+topW,horizon],[W*.96,H],[W*.04,H]],'#343b39');pathPoly([[cx-topW,horizon],[cx-topW+W*.025,horizon],[W*.13,H],[W*.04,H]],'#ead9b4');pathPoly([[cx+topW-W*.025,horizon],[cx+topW,horizon],[W*.96,H],[W*.87,H]],'#ead9b4');
// rumble strips
for(let i=0;i<18;i++){let p=((i/18+roadOffset*.018)%1),y=horizon+p*p*(H*.74),w=W*(.03+p*.1),shift=Math.sin(roadOffset*.22+p*1.6)*W*.08;ctx.fillStyle=i%2?'#e4d7b7':'#ce6849';ctx.fillRect(W/2+shift-w,y,w*.18,Math.max(3,H*.008*p));ctx.fillRect(W/2+shift+w*.82,y,w*.18,Math.max(3,H*.008*p))}
// dashed center line
for(let i=0;i<12;i++){let p=((i/12+roadOffset*.025)%1),y=horizon+p*p*(H*.75),shift=Math.sin(roadOffset*.22+p*1.6)*W*.08;ctx.fillStyle='#e9e3cb';ctx.fillRect(W/2+shift-W*.004,y,W*.008,Math.max(2,H*.035*p))}
// scenery posts and billboards
for(let i=0;i<12;i++){let z=((i*15+roadOffset*42)%145)+4;let p=1-z/150,y=horizon+p*p*(H*.74),shift=Math.sin(roadOffset*.22+(1-p)*1.6)*W*.08,x=W/2+shift+(i%2?1:-1)*W*(.18+p*.15);let s=.2+p*.8;ctx.fillStyle='#333c35';ctx.fillRect(x-W*.004*s,y-H*.1*s,W*.008*s,H*.11*s);if(i%3===0){ctx.fillStyle='#df6c48';ctx.fillRect(x-W*.04*s,y-H*.15*s,W*.08*s,H*.045*s);ctx.fillStyle='#fff0ce';ctx.font=`900 ${Math.max(5,9*s)}px Inter`;ctx.textAlign='center';ctx.fillText('WRECK',x,y-H*.12*s)}}
// rivals, ahead/behind projection uses relative race progress
for(const b of raceBots){let delta=b.dist-raceDist,z=62-delta*.48;if(z<2||z>145)continue;const [x,y,s]=project(b.x,z);drawCar(x,y,W*.055*s,H*.045*s,b.color,false,b.hit>0)}
// player's ride
const cxp=W/2+carX*W*.09,yp=H*.82;drawCar(cxp,yp,W*.12,H*.105,'#d5fa52',true,false);ctx.fillStyle='#e8f0d7';ctx.font=`900 ${Math.max(10,W*.013)}px Barlow Condensed`;ctx.textAlign='center';ctx.fillText('SCRAPHAWK',cxp,yp+H*.095);
// speed streaks while fast
if(speed>125){ctx.strokeStyle='#ffffff24';ctx.lineWidth=2;for(let i=0;i<10;i++){let x=(i*127+Math.sin(t*7+i)*50)%W,y=(i*91+t*330)%H;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(x<W/2?-18:18),y+28);ctx.stroke()}}
}
function drawCar(x,y,w,h,color,player,damaged){ctx.save();ctx.translate(x,y);ctx.fillStyle='#0007';ctx.beginPath();ctx.ellipse(0,h*.12,w*.7,h*.19,0,0,7);ctx.fill();ctx.fillStyle='#151a19';ctx.fillRect(-w*.54,-h*.23,w*.17,h*.59);ctx.fillRect(w*.37,-h*.23,w*.17,h*.59);ctx.fillStyle=damaged?'#77756b':color;ctx.beginPath();ctx.moveTo(-w*.48,-h*.08);ctx.lineTo(-w*.38,-h*.49);ctx.lineTo(-w*.19,-h*.71);ctx.lineTo(w*.21,-h*.71);ctx.lineTo(w*.4,-h*.48);ctx.lineTo(w*.49,-h*.08);ctx.lineTo(w*.39,h*.1);ctx.lineTo(-w*.4,h*.1);ctx.closePath();ctx.fill();ctx.fillStyle='#273d3d';ctx.beginPath();ctx.moveTo(-w*.28,-h*.48);ctx.lineTo(-w*.16,-h*.65);ctx.lineTo(w*.16,-h*.65);ctx.lineTo(w*.29,-h*.48);ctx.closePath();ctx.fill();ctx.fillStyle=player?'#f7f1d8':'#ffe6ad';ctx.fillRect(-w*.4,-h*.15,w*.13,h*.1);ctx.fillRect(w*.27,-h*.15,w*.13,h*.1);ctx.fillStyle='#df523c';ctx.fillRect(-w*.39,h*.01,w*.12,h*.08);ctx.fillRect(w*.27,h*.01,w*.12,h*.08);if(player){ctx.strokeStyle='#fff3c8';ctx.lineWidth=Math.max(1,w*.045);ctx.beginPath();ctx.moveTo(-w*.36,-h*.28);ctx.lineTo(w*.32,-h*.3);ctx.stroke();ctx.fillStyle='#5e5038';ctx.fillRect(-w*.08,-h*.08,w*.16,h*.04)}ctx.restore()}
function draw(t){ctx.clearRect(0,0,W,H);if(state==='scavenge'||state==='title'||state==='shop'||state==='result'&&round===1)drawJunkyard(t);else drawRace(t);if(shake>0){shake-=.016;ctx.save();ctx.translate((Math.random()-.5)*8,(Math.random()-.5)*8)}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*.016;p.y+=p.vy*.016;p.vy+=2;p.life-=.016;ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1;if(shake>0)ctx.restore();if(state==='race')drawRace(t)}

